// App commands get autogenerated `allow-<command>` permissions, so the webview
// can call them only when capabilities/default.json grants them explicitly.
const COMMANDS: &[&str] = &[
    "device_key_public",
    "device_key_sign",
    "token_get",
    "token_set",
    "token_clear",
    "config_get",
    "config_set",
    "open_url",
];

fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)),
    )
    .expect("failed to run tauri-build");
}
